// This is simplified — how Boot's auto-configuration classes look
@Configuration
@ConditionalOnClass(DataSource.class)       // only if JPA is on classpath
@ConditionalOnMissingBean(DataSource.class) // only if user hasn't defined one
public class DataSourceAutoConfiguration {
    @Bean
    public DataSource dataSource() { /* auto-configured */ }
}

@SpringBootApplication(
    exclude = { DataSourceAutoConfiguration.class }
)
public class MyApp {
    public static void main(String[] args) {
        SpringApplication.run(MyApp.class, args);
    }
}

@Configuration
public class MyConfig {
    // Defining this bean prevents Boot's DataSource auto-config from running
    @Bean
    public DataSource dataSource() {
        HikariDataSource ds = new HikariDataSource();
        ds.setJdbcUrl("jdbc:postgresql://localhost/mydb");
        ds.setMaximumPoolSize(20); // custom pool size
        return ds;
    }
}

@Service
@ConditionalOnProperty(
    name = "feature.email.enabled",
    havingValue = "true",
    matchIfMissing = false
)
public class EmailNotificationService {
    public void send(String to, String body) { /* real email */ }
}

@Configuration
@Profile("dev")  // only active in dev profile
public class DevConfig {
    @Bean
    public PaymentService paymentService() {
        return new MockPaymentService(); // fake in dev
    }
}
